async function salirDeGuardia(chofer) {
  let intentos = 0;
  for (;;) {
    intentos++;
    const c = await pool.connect();
    try {
      await c.query(`begin isolation level ${nivel}`);
      const { rows } = await c.query('select count(*)::int as n from guardia where de_guardia');
      await new Promise(r => setTimeout(r, 50));   // el tiempo en que «la persona piensa»
      if (rows[0].n <= 3) { await c.query('rollback'); return { chofer, salio: false, intentos }; }
      await c.query('update guardia set de_guardia = false where chofer = $1', [chofer]);
      await c.query('commit');
      return { chofer, salio: true, intentos };
    } catch (e) {
      await c.query('rollback').catch(() => {});
      if (e.code === '40001' && intentos < 20) continue;  // se repite TODA la transacción
      throw e;
    } finally { c.release(); }
  }
}
